INSERT INTO "app_settings" ("key", "value", "description", "updated_at") VALUES ('page_profile', '{"email":"koryandikcibadak@gmail.com","phone":"0857-8047-0481","vision":"Mewujudkan tata kelola administrasi pendidikan dasar Kecamatan Cibadak yang prima, teratur, transparan, dan akuntabel berbasis teknologi informasi.","address":"Jl. Puskemas Belakang Kantor Kec. Cibadak, Kab. Sukabumi, Jawa Barat 43351","mission":["Mengembangkan infrastruktur pelaporan berkas satu pintu secara digital.","Meningkatkan disiplin dan kepatuhan administrasi sekolah binaan.","Menyajikan data profil, wilayah, dan peta koordinasi yang transparan bagi publik.","Memperkuat sinergi antara sekolah, koordinator gugus, pengawas bina, KKKS, dan PGRI."]}'::jsonb, 'Profil informasi Koryandik, alamat, kontak, visi & misi.', '2026-07-08T02:14:45.934574+00:00') ON CONFLICT DO NOTHING;
