INSERT INTO "app_settings" ("key", "value", "description", "updated_at") VALUES ('page_faqs', '[{"id":"u1","icon":"fa-circle-info","answer":"Koryandik (Koordinator Layanan Administrasi Pendidikan) adalah portal digital terpadu untuk mengkoordinasikan pengumpulan, verifikasi, dan pemantauan berkas administrasi pendidikan se-Kecamatan Cibadak, Kabupaten Sukabumi.","category":"Umum","question":"Apa itu Koryandik?"},{"id":"u2","icon":"fa-users","answer":"Portal Koryandik dapat diakses oleh 6 peran berbeda: Operator Sekolah, Koordinator Gugus, Pengawas Bina, Ketua KKKS, Ketua PGRI, dan Administrator Koryandik.","category":"Umum","question":"Siapa saja yang dapat mengakses portal ini?"},{"id":"u3","icon":"fa-hand-holding-heart","answer":"Ya, portal Koryandik sepenuhnya gratis untuk digunakan oleh seluruh satuan pendidikan di Kecamatan Cibadak.","category":"Umum","question":"Apakah portal ini gratis?"},{"id":"p1","icon":"fa-right-to-bracket","answer":"Klik tombol \"Masuk Portal\" di halaman beranda, pilih tab \"Sekolah\", pilih nama sekolah Anda dan masukkan NPSN sekolah sebagai kode akses.","category":"Penggunaan","question":"Bagaimana cara login sebagai operator sekolah?"},{"id":"p2","icon":"fa-cloud-arrow-up","answer":"Dari Dashboard Sekolah, pilih kategori berkas yang ingin diunggah, masukkan nama file, kemudian tempelkan tautan Google Drive berkas Anda.","category":"Penggunaan","question":"Bagaimana cara mengunggah berkas?"}]'::jsonb, 'Daftar pertanyaan dan jawaban FAQ publik.', '2026-07-21T07:42:15.548676+00:00') ON CONFLICT DO NOTHING;
